mobileCSS:
/* ==================== STILI MOBILE CSC PREMIUM (solo sotto 1280px) ==================== */
@media (max-width: 1279px) {

  .header-row {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    z-index: 30;
    background: transparent;
    pointer-events: none;
  }

  /* ================= TITLE ================= */

  .title-group {
    background:
      linear-gradient(180deg,
        rgba(22,30,42,0.96),
        rgba(12,18,28,0.94));

    border: 1px solid rgba(255,255,255,0.07);

    border-radius: 14px;

    padding: 12px 15px;

    max-width: 68%;

    box-shadow:
      0 10px 24px rgba(0,0,0,0.35),
      inset 0 1px 0 rgba(255,255,255,0.03);

    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);

    pointer-events: auto;

    cursor: grab;
    user-select: none;

    position: absolute;
    top: 18px;
    left: 18px;

    z-index: 50;
  }

  .title {
    font-size: 15px;
    line-height: 1.25;
    font-weight: 800;
    letter-spacing: -0.02em;

    color: #f8fafc;

    margin: 0;
  }

  .subtitle,
  .sources {
    display: none !important;
  }

  /* ================= ACTIONS ================= */

  .actions {
    display: flex;
    flex-direction: column;
    gap: 9px;

    align-items: flex-end;

    position: absolute;
    right: 12px;
    top: 12px;

    z-index: 40;

    pointer-events: auto;
  }

  .btn {
    background:
      linear-gradient(180deg,
        rgba(22,30,42,0.96),
        rgba(10,18,28,0.94));

    border: 1px solid rgba(255,255,255,0.07);

    color: #f8fafc;

    width: 50px;
    height: 50px;

    padding: 0;

    border-radius: 14px;

    cursor: pointer;

    display: flex;
    align-items: center;
    justify-content: center;

    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);

    box-shadow:
      0 8px 20px rgba(0,0,0,0.30),
      inset 0 1px 0 rgba(255,255,255,0.03);

    transition:
      transform 0.15s ease,
      border-color 0.15s ease,
      background 0.15s ease,
      box-shadow 0.15s ease;
  }

  .btn:active {
    transform: scale(0.95);

    border-color: rgba(34,211,238,0.18);

    background:
      linear-gradient(180deg,
        rgba(34,211,238,0.10),
        rgba(10,18,28,0.95));

    box-shadow:
      0 4px 14px rgba(0,0,0,0.25),
      0 0 12px rgba(34,211,238,0.10);
  }

  .btn svg {
    width: 23px;
    height: 23px;

    fill: currentColor;
  }

  .btn.nav-btn {
    color: #22d3ee;
  }

  .btn.nav-btn svg {
    width: 26px;
    height: 26px;

    stroke: currentColor;
    stroke-width: 2.5;

    fill: none;
  }

  /* ================= CHART POSITION ================= */

  #full-capture-area {
    padding-right: 72px;
    padding-left: 6px;
  }

  .chart-container {
    justify-content: center;
    align-items: center;
  }

  .chart-container img {
    max-width: 100%;
    max-height: 100%;

    object-fit: contain;

    border-radius: 12px;

    box-shadow:
      0 14px 36px rgba(0,0,0,0.40),
      0 0 0 1px rgba(255,255,255,0.03);
  }
}

@media (max-width: 1279px) and (hover: none) and (pointer: coarse) {
  #prev-btn,
  #next-btn {
    display: none !important;
  }
}
